# apl-source:7
def تأكد_يساوي(فعلي, متوقع, اسم):
    # apl-source:8
    if فعلي != متوقع:
        # apl-source:9
        print("فشل:", اسم, "| متوقع:", متوقع, "| فعلي:", فعلي)
        # apl-source:10
        قياسي_نظام_اخرج(1)
    # apl-source:11
    print("ناجح:", اسم)
# apl-source:12

# apl-source:13

# apl-source:14
# قراءة الرقم القومي المصري (14 رقماً): الميلاد والمحافظة والنوع
# apl-source:15
def حلل_رقم_قومي(رقم):
    # apl-source:16
    قرون = {"2": 1900, "3": 2000}
    # apl-source:17
    محافظات = {"01": "القاهرة", "02": "الإسكندرية", "03": "بورسعيد", "11": "دمياط", "12": "الدقهلية", "13": "الشرقية", "14": "القليوبية", "15": "كفر الشيخ", "16": "الغربية", "17": "المنوفية", "18": "البحيرة", "19": "الإسماعيلية", "21": "الجيزة", "22": "بني سويف", "23": "الفيوم", "24": "المنيا", "25": "أسيوط", "26": "سوهاج", "27": "قنا", "28": "أسوان", "29": "الأقصر", "31": "البحر الأحمر", "32": "الوادي الجديد", "33": "مطروح", "34": "شمال سيناء", "35": "جنوب سيناء", "88": "خارج الجمهورية"}
    # apl-source:18
    سنة = قرون[رقم[0]] + int(رقم[1:3])
    # apl-source:19
    شهر = int(رقم[3:5])
    # apl-source:20
    يوم = int(رقم[5:7])
    # apl-source:21
    محافظة = محافظات[رقم[7:9]]
    # apl-source:22
    تسلسل = int(رقم[9:12])
    # apl-source:23
    جندر = "ذكر"
    # apl-source:24
    if تسلسل % 2 == 0:
        # apl-source:25
        جندر = "أنثى"
    # apl-source:26
    return [سنة, شهر, يوم, محافظة, جندر]
# apl-source:27

# apl-source:28
نتيجة = حلل_رقم_قومي("30009091234467")
# apl-source:29
print("النتيجة:", نتيجة)
# apl-source:30
تأكد_يساوي(نتيجة[0], 2000, "سنة الميلاد")
# apl-source:31
تأكد_يساوي(نتيجة[3], "الدقهلية", "المحافظة")
# apl-source:32
تأكد_يساوي(نتيجة[4], "أنثى", "النوع من التسلسل الزوجي")
# apl-source:33
